fn rsa_wpt_keys(name string, hash string) CryptoKeyPair {
	handle := rsa_wpt_private_handle()
	algorithm := RsaHashedKeyAlgorithm{ name: name, modulus_length: 2048, public_exponent: handle.public_exponent, hash: hash }
	return CryptoKeyPair{
		private_key: CryptoKey.create_with_internal_handle(.private_key, true, algorithm, rsa_allowed_usages(name, true), handle)
		public_key:  CryptoKey.create_with_internal_handle(.public_key, true, algorithm, rsa_allowed_usages(name, false), RsaPublicKeyHandle{ modulus: handle.modulus, public_exponent: handle.public_exponent })
	}
}

fn test_rsa_all_upstream_wpt_operation_vectors_and_real_roundtrips() {
	subtle := SubtleCrypto.create()
	for vector in rsa_source_vectors {
		pair := rsa_wpt_keys(vector.name, vector.hash)
		message := hex.decode(vector.message_hex)!
		if vector.name == 'RSA-OAEP' {
			params := RsaOaepParams{ label: hex.decode(vector.label_hex)! }
			assert subtle.decrypt(params, pair.private_key, hex.decode(vector.ciphertext_hex)!)! == message
			assert subtle.decrypt(params, pair.private_key, subtle.encrypt(params, pair.public_key, message)!)! == message
		} else if vector.name == 'RSA-PSS' {
			params := RsaPssParams{ salt_length: vector.salt }
			assert subtle.verify(params, pair.public_key, hex.decode(vector.signature_hex)!, message)!
			assert !subtle.verify(params, pair.public_key, hex.decode(vector.signature_hex)!, [u8(1)])!
			generated := subtle.sign(params, pair.private_key, message)!
			assert subtle.verify(params, pair.public_key, generated, message)!
			if vector.salt == 0 {
				assert generated.hex() == vector.signature_hex
			}
		} else {
			assert subtle.sign(vector.name, pair.private_key, message)!.hex() == vector.signature_hex
			assert subtle.verify(vector.name, pair.public_key, hex.decode(vector.signature_hex)!, message)!
			assert !subtle.verify(vector.name, pair.public_key, hex.decode(vector.signature_hex)!, [u8(1)])!
		}
	}
}

fn test_rsa_source_operation_errors_and_label_and_salt_mismatch() {
	subtle := SubtleCrypto.create()
	pair := rsa_wpt_keys('RSA-OAEP', 'SHA-256')
	params := RsaOaepParams{ label: 'label'.bytes() }
	ciphertext := subtle.encrypt(params, pair.public_key, 'message'.bytes())!
	if _ := subtle.decrypt(RsaOaepParams{}, pair.private_key, ciphertext) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Failed to encrypt'
	}
	if _ := subtle.encrypt(params, pair.public_key, []u8{len: 191}) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Failed to encrypt'
	}
	if _ := RSAOAEP.create().encrypt(params, pair.private_key, []) {
		assert false
	} else {
		assert err.msg() == 'InvalidAccessError: Key is not a public key'
	}
	if _ := RSAOAEP.create().decrypt(params, pair.public_key, []) {
		assert false
	} else {
		assert err.msg() == 'InvalidAccessError: Key is not a private key'
	}
	invalid_hash := rsa_wpt_keys('RSA-OAEP', 'SHA3-256')
	if _ := subtle.encrypt(params, invalid_hash.public_key, []) {
		assert false
	} else {
		assert err.msg() == "OperationError: Invalid hash function 'SHA3-256'"
	}
	pss := rsa_wpt_keys('RSA-PSS', 'SHA-256')
	signature := subtle.sign(RsaPssParams{ salt_length: 32 }, pss.private_key, [])!
	assert !subtle.verify(RsaPssParams{ salt_length: 0 }, pss.public_key, signature, [])!
	if _ := subtle.sign(RsaPssParams{ salt_length: 1000 }, pss.private_key, []) {
		assert false
	} else {
		assert err.msg() == 'OperationError: Failed to sign message'
	}
	if _ := RSAPSS.create().sign(RsaPssParams{}, pss.public_key, []) {
		assert false
	} else {
		assert err.msg() == 'InvalidAccessError: Key is not a private key'
	}
	if _ := RSASSAPKCS1.create().verify(AlgorithmParams{}, pss.private_key, [], []) {
		assert false
	} else {
		assert err.msg() == 'InvalidAccessError: Key is not a public key'
	}
}

@[heap]
struct RsaOperationBindingHost {
mut:
	work   []fn ()
	settle []fn ()
}

fn test_rsa_promise_oaep_copies_label_and_message_and_uses_crypto_settlement() {
	mut host := &RsaOperationBindingHost{}
	binding := SubtleCryptoBinding.create(SubtleCrypto.create(), webidl.PromiseContext{}, fn [mut host] (task fn ()) {
		host.work << task
	}, fn [mut host] (task fn ()) { host.settle << task })
	pair := rsa_wpt_keys('RSA-OAEP', 'SHA-256')
	mut label := webidl.BufferSource.array_buffer('label'.bytes())
	mut message := webidl.BufferSource.array_buffer('message'.bytes())
	algorithm := webidl.object_value({
		'name':  webidl.string_value('RSA-OAEP')
		'label': webidl.buffer_source_value(label)
	})
	promise := binding.encrypt(algorithm, pair.public_key, message)
	label.write('other'.bytes(), 0)!
	message.write([u8(0)], 0)!
	assert promise.state == .pending
	host.work[0]()
	assert promise.state == .pending
	host.settle[0]()
	assert promise.state == .fulfilled
	ciphertext := promise.result.buffer_value or { panic('ciphertext') }
	assert SubtleCrypto.create().decrypt(RsaOaepParams{ label: 'label'.bytes() }, pair.private_key, webidl.get_buffer_source_copy(ciphertext))! == 'message'.bytes()
	signing_pair := rsa_wpt_keys('RSA-PSS', 'SHA-256')
	signing := binding.sign(webidl.object_value({
		'name':       webidl.string_value('RSA-PSS')
		'saltLength': webidl.number_value(0)
	}), signing_pair.private_key, webidl.BufferSource.array_buffer([]))
	host.work[1]()
	assert signing.state == .pending
	host.settle[1]()
	assert signing.state == .fulfilled
	signature := signing.result.buffer_value or { panic('signature') }
	assert SubtleCrypto.create().verify(RsaPssParams{ salt_length: 0 }, signing_pair.public_key, webidl.get_buffer_source_copy(signature), [])!
}
